scwin.usrId = js_id;

///////// 2. 초기화 영역 /////////
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
scwin.txa_title_onchange = function(info) {
    try {
        scwin.is80bytes(1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.txa_title_onchange" });
    }
};

scwin.img_send_onclick = function(e) {
    try {
        scwin.sendSMS();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.img_send_onclick" });
    }
};

scwin.MxCombo_1_onselchange = function(info) {
    try {
        // alert(MxCombo_1.Index);
        if (MxCombo_1.getSelectedIndex() === 2) {
            txa_title.Text = "[운영]상장공시시스템 정상 가동.\r\nATS공개장 개시 수신 확인.\r\n시간외단일가공시 유,코 생성 확인.\r\n금일당번:";
            MxCombo_2.setSelectedIndex(0);
        } else if (MxCombo_1.getSelectedIndex() === 3) {
            txa_title.Text = "[운영]상장공시시스템 정상 마감(채권포함)";
            MxCombo_2.setSelectedIndex(4); // 0->2  마감시 현업문자전송 제외 20130926 yanghy  당분간 운영팀 부서장님까지 모두 넣은 2018.04.02

        } else if (MxCombo_1.getSelectedIndex() === 0) {
            txa_title.Text = "[운영]상장공시시스템 1차 점검 정상.금일당번: ";
            MxCombo_2.setSelectedIndex(4);
        } else if (MxCombo_1.getSelectedIndex() === 1) {
            txa_title.Text = "[운영]정보분배 정상확인 완료";
            MxCombo_2.setSelectedIndex(0);
        } else {
            txa_title.Text = "[운영]";
        }

        // 삭제해도 다시 나오도록
        // if(dts_Receiver.CountRow == 0) {
        scwin.setGrdReceiver();
        // }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.MxCombo_1_onselchange" });
    }
};

scwin.MxCombo_2_onselchange = function(info) {
    try {
        if (dts_rcv.getRowCount() === 0) {
            alert("수신자 그룹 조회 오류");
            return;
        }
        scwin.setGrdReceiver();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.MxCombo_2_onselchange" });
    }
};

scwin.trs_Save_OnSuccess = function(e) {
    try {
        txa_title.text = "";
        alert('전송 완료');
        scwin.setClear();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.trs_Save_OnSuccess" });
    }
};

scwin.trs_Save_OnFail = function(e) {
    try {
        txa_title.text = "";
        alert('전송 실패');
        scwin.setClear();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.trs_Save_OnFail" });
    }
};

scwin.grd_Receiver_onheadcheckclick = function(headerId) {
    try {
        let check = 'F';
        if (col === 1) {
if (bCheck === 1) check = 'T';
            dts_Receiver.setBroadcast(false);
            // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
            for (i = 1; i <= dts_Receiver.getRowCount(); i++) {
                dts_Receiver.setCellData(i, "CHECK", check);
            }
            dts_Receiver.setBroadcast(true, true);
}
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.grd_Receiver_onheadcheckclick" });
    }
};

scwin.dts_rcv_OnLoadCompleted = function(e) {

};

scwin.img_srch_onclick = function(e) {
    try {
        dts_Receiver.insertRow();

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "CHECK", "T");

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_PHONE", "");

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_TEAM", "기타");

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_NAME", "");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.img_srch_onclick" });
    }
};

scwin.image_2_onclick = function(e) {
    try {
        scwin.deleteRows(dts_Receiver);
        // dts_Receiver.DeleteRow(dts_Receiver.RowPosition);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT30309.image_2_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
scwin.setDefault = async function() {
    const sbmOptions = {
        id : "sbm_dts_msg",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_msg=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    dts_msg.insertRow();
    const sbmOptions2 = {
        id : "sbm_dts_Receiver",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Receiver=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    scwin.getListSmsRcv();
};

scwin.getListSmsRcv = async function() {
    url += "&SEARCH_DSC=SMS";
    url += "&SCREN_ID=" + 'ULDMGT30309.gfm';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_rcv",
        action : "/sms.do",
        ref : "",
        target : "dts_rcv=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.dts_rcv_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
scwin.getStringSize = function(message) {
    let i, len = 0;
    for (i = 0; i < message.length; i++) {
        (message.charCodeAt(i) > 255) ? len += 2: len++;
    }
    return len;
};

scwin.sendSMS = function() {
    if (scwin.isValidate()) {
        const res = window.confirm("전송하시겠습니까?");
        if (res) {
            let url = "/sms.do?method=sendSMS" + "&SCREN_ID=" + 'ULDMGT30309.gfm' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.Action = url;
            trs_Save.KeyName = "toinb_dataid4";
            // TODO Stage2: Gauce 통신(DataID/KeyValue/Post) — executeDynamic 재설계 필요(규칙 12/16)
            trs_Save.KeyValue = "JSP(I:pInputMsg=dts_msg, I:pInputData=dts_Receiver)";

            trs_Save.post();
        }
    }
};

scwin.isValidate = function() {
    if (scwin.is80bytes(0) && scwin.isSenderNotNull() && scwin.isReceiverNotNull()) {
        scwin.allCheckReceiver();
        return true;
    } else return false;
};

scwin.allCheckReceiver = function() {
    dts_Receiver.setBroadcast(false);
    // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
    for (let i = 1; i <= dts_Receiver.getRowCount(); i++) {
        dts_Receiver.setCellData(i, "CHECK", "T");
    }
    dts_Receiver.setBroadcast(true, true);
};

scwin.isSenderNotNull = function() {
    const sendNum = txb_snd_no.value;
    if (sendNum === "" || sendNum.length === 0) {
        alert("보내는 번호를 입력하십시오.");
        return false;
    }
    return true;
};

scwin.isReceiverNotNull = function() {
    if (dts_Receiver.getRowCount() === 0) {
        alert("받는 사람이 지정되지 않았습니다.");
        return false;
    } else {
        // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
        for (let i = 1; i <= dts_Receiver.getRowCount(); i++) {
            if (dts_Receiver.getCellData(i, "RCV_PHONE") === "") {
                alert("휴대폰 번호가 입력되지 않은 항목이 존재합니다. \r\n필요없는 항목을 삭제하고 진행하십시오.");
                return false;
            }
        }
    }
    return true;
};

scwin.is80bytes = function(ver) {
    const textVal = scwin.getStringSize(txa_title.text);
    txb_title_size.setValue(textVal);
    if (textVal > 2000) {
        alert('2000byte가 초과되었습니다.');
        txa_title.text = scwin.get2000bytes(txa_title.text);
        txb_title_size.setValue(scwin.getStringSize(txa_title.text));

        txa_title.Focus();
        return false;
    } else if (textVal === 0) {
        if (ver === 0) {
            alert('보낼 메세지를 입력하십시오.');

            txa_title.Focus();
            return false;
        }
    }
    return true;
};

scwin.get2000bytes = function(message) {
    let len = 0;
    let i = 0;
    for (i; i < message.length; i++) {
        if (message.charCodeAt(i) > 255) {
            if ((len + 2) > 2000) break;

            else len += 2;
        } else {
            if ((len + 1) > 2000) break;

            else len++;
        }
    }
    return message.substring(0, i);
};

scwin.deleteRows = function(obj) {
for (let i = obj.getRowCount() - 1; i >= 0; i--) {
        if (obj.getCellData(i, "CHECK") === "T") obj.removeRow(i);
    }

    $c.cm.setColumnProp(grd_Receiver, 'CHECK', 'HeadCheck', "false");
};

scwin.setClear = function() {
    dts_Receiver.setJSON([]);

    $c.cm.setColumnProp(grd_Receiver, 'CHECK', 'HeadCheck', "false");
};

scwin.setGrdReceiver = function() {
krxP = new Array();
    grp = new Array();

    // 등록된 수신그룹 순서
    // TODO Stage2: 0-based 인덱스 검토(비정형 루프 — 토큰만 치환)
    for (i = 1; i <= dts_rcv.getRowCount(); i++) {
        grp[i - 1] = dts_rcv.getCellData(i, "TEXT").split(",");
    }
    if (dts_Receiver.getRowCount() > 0) {
        dts_Receiver.removeAll();
    }

    // 0:IT현업,1:운영팀,2:현업기타
    if (MxCombo_2.getSelectedIndex() === 0) {
        // 시작마감
        krxP = grp[0].concat(grp[1]);
    } else if (MxCombo_2.getSelectedIndex() === 1) {
        // 운영팀
        krxP = grp[0];
    } else if (MxCombo_2.getSelectedIndex() === 2) {
        // KRX(BENIT)
        krxP = grp[1];
    } else if (MxCombo_2.getSelectedIndex() === 3) {
        // 기타
        krxP = grp[2];
    } else if (MxCombo_2.getSelectedIndex() === 4) {
        // 1차점검SMS
        krxP = grp[0].concat(grp[2]).concat(grp[1]);
    }
    dts_Receiver.setBroadcast(false);
    for (i = 0; i < krxP.length; i++) {
        dts_Receiver.insertRow();
        e = krxP[i].split("|");

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "CHECK", "F");

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_PHONE", e[0]);

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_NAME", e[1]);

        dts_Receiver.setCellData(dts_Receiver.getFocusedRowIndex(), "RCV_TEAM", e[2]);
    }
    dts_Receiver.setBroadcast(true, true);
};

scwin.grd_Receiver_CanColumnPosChange = function(row, colid) {
    return true;
};

scwin.gform_onload = function() {
    $c.session.sessionCheck();
    scwin.setDefault();
};
